window.App.icon = function (name, size, cls) {
  var d = window.App.icons[name];
  if (!d) return '';
  var w = size || 22;
  var parts = d.vb.split(' ');
  var h = Math.round(w * parts[3] / parts[2]);
  return '<svg class="sf-icon ' + (cls || '') + '" width="' + w + '" height="' + h + '" viewBox="' + d.vb + '" ' + d.attrs + ' aria-hidden="true" focusable="false">' + d.inner + '</svg>';
};
